import React, { useEffect, useState } from "react";
import { useSearchParams } from "react-router-dom";
import { httpService } from "../../../httpService";

import {
  Avatar,
  Box,
  Card,
  CardContent,
  Chip,
  CircularProgress,
  Divider,
  Paper,
  Stack,
  Typography,
} from "@mui/material";

import { Table } from "react-bootstrap";

function ViewClassPage() {
  const [params] = useSearchParams();

  const [classData, setClassData] = useState(null);
  const [students, setStudents] = useState([]);
  const [teachers, setTeachers] = useState([]);
  const [loading, setLoading] = useState(true);

  const classId = params.get("class");

  const getData = async () => {
    try {
      setLoading(true);

      const { data } = await httpService("admin/viewclass", {
        params: { class: classId },
      });

      if (data) {
        setClassData(data.classData);
        setStudents(data.students);
        setTeachers(data.teachers);
      }
    } catch (error) {
      console.log(error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    getData();
  }, []);

  if (loading) {
    return (
      <Box
        sx={{
          height: "70vh",
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
        }}
      >
        <CircularProgress />
      </Box>
    );
  }

  return (
    <Box
      sx={{
        p: { xs: 2, md: 4 },
        backgroundColor: "#f8fafc",
        minHeight: "100vh",
      }}
    >
      {/* PAGE HEADER */}
      <Stack
        direction={{ xs: "column", md: "row" }}
        justifyContent="space-between"
        alignItems={{ xs: "flex-start", md: "center" }}
        mb={4}
        spacing={2}
      >
        <Box>
          <Typography variant="h4" textTransform={"uppercase"} fontWeight={700}>
            {classData?.name}
          </Typography>

          <Typography color="text.secondary">
            Class Management Overview
          </Typography>
        </Box>

        <div>
          <Stack direction={"row"} spacing={1}>
            <Chip
              label={`${students.length} Student${students.length > 1 ? "s" : ""}`}
              color="primary"
              sx={{
                fontWeight: 600,
                px: 1,
              }}
            />
            <Chip
              label={`${teachers.length} Teacher${teachers.length > 1 ? "s" : ""}`}
              color="warning"
              sx={{
                fontWeight: 600,
                px: 1,
              }}
            />
          </Stack>
        </div>
      </Stack>

      {/* CLASS SUMMARY CARD */}
      <Card
        elevation={0}
        sx={{
          borderRadius: 4,
          mb: 4,
          border: "1px solid #e2e8f0",
        }}
      >
        <CardContent>
          <Typography variant="h6" fontWeight={700} gutterBottom>
            Class Information
          </Typography>

          <Divider sx={{ my: 2 }} />

          <Stack spacing={1}>
            <Typography>
              <strong>Class Name:</strong> {classData?.name}
            </Typography>

            <Typography>
              <strong>Total Students:</strong> {students.length}
            </Typography>
          </Stack>
        </CardContent>
      </Card>

      {/* Teachers TABLE */}
      <Paper
        elevation={0}
        sx={{
          borderRadius: 4,
          overflow: "hidden",
          border: "1px solid #e2e8f0",
          marginBottom: 4,
        }}
      >
        <Box
          sx={{
            p: 3,
            borderBottom: "1px solid #e2e8f0",
            backgroundColor: "white",
          }}
        >
          <Typography variant="h6" fontWeight={700}>
            Teachers
          </Typography>
        </Box>

        <div className="table-responsive">
          <Table hover className="mb-0 align-middle">
            <thead
              style={{
                background: "#f1f5f9",
              }}
            >
              <tr>
                <th className="py-3 px-3">#</th>
                <th className="py-3">Teacher</th>
                <th className="py-3">Phone Number</th>
                <th className="py-3">Gender</th>
              </tr>
            </thead>

            <tbody>
              {teachers.map((s, idx) => (
                <tr key={idx} className="text-capitalize">
                  <td className="px-3 fw-semibold">{idx + 1}</td>

                  <td>
                    <Stack direction="row" spacing={2} alignItems="center">
                      <Avatar>{s.lastName?.charAt(0)}</Avatar>

                      <Box>
                        <Typography fontWeight={600}>
                          {s.lastName} {s.firstName}
                        </Typography>

                        <Typography variant="body2" color="text.secondary">
                          Teacher
                        </Typography>
                      </Box>
                    </Stack>
                  </td>

                  <td>{s.phoneNumber}</td>

                  <td>
                    <Chip
                      label={s.gender}
                      size="small"
                      color={
                        s.gender?.toLowerCase() === "male"
                          ? "primary"
                          : "secondary"
                      }
                    />
                  </td>
                </tr>
              ))}
            </tbody>
          </Table>
        </div>
      </Paper>
      {/* STUDENTS TABLE */}
      <Paper
        elevation={0}
        sx={{
          borderRadius: 4,
          overflow: "hidden",
          border: "1px solid #e2e8f0",
        }}
      >
        <Box
          sx={{
            p: 3,
            borderBottom: "1px solid #e2e8f0",
            backgroundColor: "white",
          }}
        >
          <Typography variant="h6" fontWeight={700}>
            Students
          </Typography>
        </Box>

        <div className="table-responsive">
          <Table hover className="mb-0 align-middle">
            <thead
              style={{
                background: "#f1f5f9",
              }}
            >
              <tr>
                <th className="py-3 px-3">#</th>
                <th className="py-3">Student</th>
                <th className="py-3">Phone Number</th>
                <th className="py-3">Gender</th>
              </tr>
            </thead>

            <tbody>
              {students.map((s, idx) => (
                <tr key={idx} className="text-capitalize">
                  <td className="px-3 fw-semibold">{idx + 1}</td>

                  <td>
                    <Stack direction="row" spacing={2} alignItems="center">
                      <Avatar>{s.lastName?.charAt(0)}</Avatar>

                      <Box>
                        <Typography fontWeight={600}>
                          {s.lastName} {s.firstName}
                        </Typography>

                        <Typography variant="body2" color="text.secondary">
                          Student
                        </Typography>
                      </Box>
                    </Stack>
                  </td>

                  <td>{s.phoneNumber}</td>

                  <td>
                    <Chip
                      label={s.gender}
                      size="small"
                      color={
                        s.gender?.toLowerCase() === "male"
                          ? "primary"
                          : "secondary"
                      }
                    />
                  </td>
                </tr>
              ))}
            </tbody>
          </Table>
        </div>
      </Paper>
    </Box>
  );
}

export default ViewClassPage;
